begin;
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();sid uuid;tid uuid;mid uuid;other uuid;pid uuid;counts jsonb;pts bigint;rules jsonb:='[{"unit":"legs","first_to":6,"winner_points":1,"exact_points":3}]';
begin
 if to_regclass('auth.users') is not null then
 insert into auth.users(id,email,email_confirmed_at,aud,role) values(a,a||'@management-qa.invalid',now(),'authenticated','authenticated'),(u,u||'@management-qa.invalid',now(),'authenticated','authenticated');
 end if;
 insert into public.profiles(id,username,display_name) values(a,'mgqa-'||substr(a::text,1,20),'QA admin'),(u,'mgqa-'||substr(u::text,1,20),'QA user') on conflict do nothing;
 insert into public.user_roles values(a,'admin'),(u,'user');select id into sid from public.sports where slug='darts';
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('role','authenticated',true);
 tid:=public.create_knockout_tournament('QA management',sid,'players',array['QA One','QA Two'],now()+interval '1 day',rules);
 other:=public.create_knockout_tournament('QA protected',sid,'players',array['QA X','QA Y'],now()+interval '1 day',rules);
 perform public.edit_knockout(other,'publish');
 perform public.manage_tournament(other,'points',jsonb_build_object('reason','QA points','rules',jsonb_build_array(jsonb_build_object('id',public.get_knockout_schema(other)->'rounds'->0->>'id','winner_points',2,'exact_points',4))));
 perform public.manage_tournament(other,'draft','{"reason":"QA back to draft"}');
 perform public.manage_tournament(other,'metadata',jsonb_build_object('reason','QA past start','name','QA protected','start',now()-interval '1 day'));
 perform public.manage_tournament(other,'metadata',jsonb_build_object('reason','QA restore start','name','QA protected','start',now()+interval '1 day'));
 perform public.manage_tournament(other,'champion',jsonb_build_object('reason','QA second config','deadline',now()+interval '1 hour','points',10,'choices',array['QA X','QA Y']));
 perform public.edit_knockout(other,'publish');
 perform public.manage_tournament(other,'metadata',jsonb_build_object('reason','QA earlier start','name','QA protected','start',now()-interval '1 hour'));
 perform public.manage_tournament(other,'metadata',jsonb_build_object('reason','QA later correction','name','QA protected','start',now()+interval '1 day'));
 if (public.get_champion_prediction(other)->>'open')::boolean then raise exception 'FAIL champion reopened after correction';end if;
 perform public.manage_tournament(other,'champion_reset','{"reason":"QA reset empty question"}');
 mid:=(public.get_knockout_schema(tid)->'matches'->0->>'id')::uuid;
 perform public.manage_tournament(tid,'metadata',jsonb_build_object('name','QA renamed','start',now()+interval '1 day','reason','QA edit'));
 perform public.edit_knockout(tid,'schedule',mid,jsonb_build_object('start',now()+interval '1 day','unit','legs','first_to',6));
 perform public.manage_tournament(tid,'champion',jsonb_build_object('deadline',clock_timestamp()+interval '3 seconds','points',10,'choices',array['QA One','QA Two'],'reason','QA config'));
 perform public.edit_knockout(tid,'publish');
 perform public.edit_knockout(tid,'roster',null,'{"names":["QA One","QA Two"]}');
 perform public.edit_knockout(tid,'open',mid,'{"reason":"QA open"}');
 perform set_config('role','postgres',true);insert into public.tournament_entries(tournament_id,user_id) values(tid,u);
 insert into public.pools(tournament_id,owner_id,name) values(tid,u,'QA pool') returning id into pid;
 insert into public.pool_members(pool_id,user_id) values(pid,u);
 perform set_config('role','authenticated',true);perform set_config('request.jwt.claim.sub',u::text,true);
 perform public.submit_champion_prediction(tid,'QA One');
 perform public.submit_match_prediction(mid,6,3);
 if public.get_champion_prediction(tid)->>'mine'<>'QA One' then raise exception 'FAIL own champion read';end if;
 begin perform public.admin_tournament_catalog();raise exception 'FAIL user management';exception when insufficient_privilege then null;end;
 begin perform public.manage_tournament(tid,'pause','{"reason":"bad user"}');raise exception 'FAIL user mutation';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.manage_tournament(tid,'pause','{"reason":"QA pause"}');
 perform set_config('request.jwt.claim.sub',u::text,true);
 begin perform public.submit_champion_prediction(tid,'QA Two');raise exception 'FAIL paused winner submit';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.manage_tournament(tid,'resume','{"reason":"QA resume"}');
 begin perform public.manage_tournament(tid,'draft','{"reason":"QA unsafe draft"}');raise exception 'FAIL draft with predictions';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 begin perform public.manage_tournament(tid,'champion',jsonb_build_object('deadline',now()+interval '1 hour','points',99,'choices',array['QA One','QA Two'],'reason','QA tamper'));raise exception 'FAIL changed bonus rules';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform pg_sleep(3.1);
 perform set_config('request.jwt.claim.sub',u::text,true);
 begin perform public.submit_champion_prediction(tid,'QA Two');raise exception 'FAIL late champion';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.edit_knockout(tid,'start',mid,'{"reason":"QA start"}');perform public.edit_knockout(tid,'result',mid,'{"home_score":6,"away_score":2}');
 select earned_points into pts from public.get_tournament_leaderboard(tid) where user_id=u;if pts<>11 then raise exception 'FAIL champion leaderboard %',pts;end if;
 select earned_points into pts from public.get_tournament_leaderboard(tid,pid) where user_id=u;if pts<>11 then raise exception 'FAIL pool champion %',pts;end if;
 perform public.edit_knockout(tid,'result',mid,'{"home_score":1,"away_score":6,"reason":"QA final correction"}');
 select earned_points into pts from public.get_tournament_leaderboard(tid) where user_id=u;if pts<>0 then raise exception 'FAIL corrected winner points';end if;
 counts:=(select x->'counts' from jsonb_array_elements(public.admin_tournament_catalog())x where x->>'id'=tid::text);
 begin perform public.manage_tournament(tid,'delete',jsonb_build_object('reason','QA delete','confirm_name','wrong','expected',counts));raise exception 'FAIL wrong delete confirmation';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform public.manage_tournament(tid,'delete',jsonb_build_object('reason','QA delete','confirm_name','QA renamed','expected',counts));
 perform set_config('role','postgres',true);
 if exists(select 1 from public.tournaments where id=tid) or exists(select 1 from public.pools where id=pid) or exists(select 1 from predict_private.champion_predictions where tournament_id=tid) then raise exception 'FAIL deletion incomplete';end if;
 if not exists(select 1 from public.tournaments where id=other) then raise exception 'FAIL other tournament touched';end if;
 if not exists(select 1 from public.match_audit_log where match_id=mid) or not exists(select 1 from predict_private.tournament_management_audit where tournament_id=tid and action='delete') then raise exception 'FAIL audits lost';end if;
 if exists(select 1 from predict_private.tournament_mutation_permits) then raise exception 'FAIL permit left';end if;
end $$;
select 'PASS tournament lifecycle, champion deadlines and points, pool ranking, deletion isolation and retained audits' as result;
rollback;
